import{_ as t,o as a,c as n,a2 as r}from"./chunks/framework.hw3Av5Vn.js";const y=JSON.parse('{"title":"Rock","description":"","frontmatter":{},"headers":[],"relativePath":"demos/ROCK.md","filePath":"demos/ROCK.md"}'),o={name:"demos/ROCK.md"};function s(i,e,l,h,d,c){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="rock" tabindex="-1">Rock <a class="header-anchor" href="#rock" aria-label="Permalink to &quot;Rock&quot;">​</a></h1><p>The demo songs in the rock style. Each is described below, with the features it uses; <a href="./../DEMOS">About Demos</a> lists every demo.</p><ul><li><a href="#aliens_counting">Synth-Rock</a>: <code>aliens_counting.yml</code></li><li><a href="#annandale">Jazz-Rock</a>: <code>annandale.yml</code></li><li><a href="#gain_distance_pedestrian">Funky Hard Rock</a>: <code>gain_distance_pedestrian.yml</code></li><li><a href="#green_men">Pop-Punk Strumming</a>: <code>green_men.yml</code></li><li><a href="#know_your_slang">Indie Rock</a>: <code>know_your_slang.yml</code></li><li><a href="#musician">Musician</a>: <code>26_musician.yml</code></li><li><a href="#not_werewolves">Outlaw Piano Rock</a>: <code>not_werewolves.yml</code></li><li><a href="#spot_over_there">Power-Pop</a>: <code>spot_over_there.yml</code></li><li><a href="#training_montage">Arena-Rock</a>: <code>training_montage.yml</code></li><li><a href="#volcano">Guitar Showpiece</a>: <code>volcano.yml</code></li><li><a href="#why_say_it_again">New Wave</a>: <code>why_say_it_again.yml</code></li></ul><p><a id="aliens_counting"></a></p><h2 id="synth-rock-aliens-counting-yml" tabindex="-1">Synth-Rock: <code>aliens_counting.yml</code> <a class="header-anchor" href="#synth-rock-aliens-counting-yml" aria-label="Permalink to &quot;Synth-Rock: `aliens_counting.yml`&quot;">​</a></h2><p>A mid-eighties synth-rock anthem in the manner of The Final Countdown (Europe), with a fanfare of its own. A fanfare on i VI iv VII and i VI iv V; a verse on i i VI VII; a chorus on the fanfare&#39;s chords, each line answered by the brass; a guitar solo, a breakdown and a last chorus twice.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/rock/aliens_counting.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/rock/aliens_counting.yml</code></a> · E minor · 118 BPM · 2:59 · 11 scenes · 10 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../generators/CHAIN">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../generators/PROGRESSION">✓</a></td></tr></tbody></table><p><a id="annandale"></a></p><h2 id="jazz-rock-annandale-yml" tabindex="-1">Jazz-Rock: <code>annandale.yml</code> <a class="header-anchor" href="#jazz-rock-annandale-yml" aria-label="Permalink to &quot;Jazz-Rock: `annandale.yml`&quot;">​</a></h2><p>A seventies jazz-rock song in the manner of Steely Dan&#39;s My Old School, with a horn line of its own. A straight groove under a pumping piano on chords with added ninths; the guitar answers each line of the verse; horns punch the chorus, which is sung high in harmony, and play a riff on I bVII IV between sections; a guitar solo over the verse.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/rock/annandale.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/rock/annandale.yml</code></a> · A major · 118 BPM · 2:59 · 9 scenes · 11 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../generators/CHAIN">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../generators/PROGRESSION">✓</a></td></tr></tbody></table><p><a id="gain_distance_pedestrian"></a></p><h2 id="funky-hard-rock-gain-distance-pedestrian-yml" tabindex="-1">Funky Hard Rock: <code>gain_distance_pedestrian.yml</code> <a class="header-anchor" href="#funky-hard-rock-gain-distance-pedestrian-yml" aria-label="Permalink to &quot;Funky Hard Rock: `gain_distance_pedestrian.yml`&quot;">​</a></h2><p>A funky hard rock song of the early seventies in the manner of Walk Away (James Gang), with a riff and tunes of its own. A syncopated riff of single notes and rests on an overdriven guitar against a funky kit with ghost notes; a bluesy verse over the riff; a chorus in harmony on IV, I and V; a solo; a long ending of two slide guitars on flat VII, IV and I.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/rock/gain_distance_pedestrian.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/rock/gain_distance_pedestrian.yml</code></a> · A major · 100 BPM · 3:02 · 10 scenes · 14 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../generators/CHAIN">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../generators/PROGRESSION">✓</a></td></tr></tbody></table><p><a id="green_men"></a></p><h2 id="pop-punk-strumming-green-men-yml" tabindex="-1">Pop-Punk Strumming: <code>green_men.yml</code> <a class="header-anchor" href="#pop-punk-strumming-green-men-yml" aria-label="Permalink to &quot;Pop-Punk Strumming: `green_men.yml`&quot;">​</a></h2><p>A fast pop-punk song in the manner of American Idiot (Green Day): a stop-start riff of power chords, and wide open choruses. A riff of power chords, two to a bar, I IV bVII IV; a verse muted for two bars and answered for two; a chorus on IV I V I; a solo over the chorus chords.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/rock/green_men.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/rock/green_men.yml</code></a> · E major · 180 BPM · 2:59 · 10 scenes · 7 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chains</th><th style="text-align:center;">guitarify</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../generators/CHAIN">✓</a></td><td style="text-align:center;"><a href="./../generators/GUITARIFY">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../generators/PROGRESSION">✓</a></td></tr></tbody></table><p><a id="know_your_slang"></a></p><h2 id="indie-rock-know-your-slang-yml" tabindex="-1">Indie Rock: <code>know_your_slang.yml</code> <a class="header-anchor" href="#indie-rock-know-your-slang-yml" aria-label="Permalink to &quot;Indie Rock: `know_your_slang.yml`&quot;">​</a></h2><p>An upbeat indie rock song in two moods after the Shins&#39; New Slang and Know Your Onion: a bass-and- strum acoustic guitar with a tambourine, then a jangling electric guitar at a faster tempo. A bass note and a strum to each chord, a tambourine in eighths and a busy bass; the second half faster and jangling, with a chorus of its own.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/rock/know_your_slang.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/rock/know_your_slang.yml</code></a> · G major · 132 BPM · 3:04 · 10 scenes · 8 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">guitarify</th><th style="text-align:center;">ties</th><th style="text-align:center;">tempo changes</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../generators/CHAIN">✓</a></td><td style="text-align:center;"><a href="./../generators/GUITARIFY">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../SCENES#scene-settings">✓</a></td><td style="text-align:center;"><a href="./../generators/PROGRESSION">✓</a></td></tr></tbody></table><p><a id="musician"></a></p><h2 id="musician-26-musician-yml" tabindex="-1">Musician: <code>26_musician.yml</code> <a class="header-anchor" href="#musician-26-musician-yml" aria-label="Permalink to &quot;Musician: `26_musician.yml`&quot;">​</a></h2><p>A band in G major whose players each have one bar. The first scene plays every pattern as written, all the time. The scenes after it hand the same patterns to Musician generators: in the verse the rhythm guitar plays softer, the hi-hat keeps to the beats, the organ sits out and the lead guitar plays only where the tune rests; in the chorus everyone plays and the organ holds each chord; in the breakdown the bass plays one hit a bar and the rhythm guitar is muted.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/26_musician.yml" target="_blank" rel="noreferrer"><code>examples/learning/26_musician.yml</code></a> · G major · 104 BPM · 2:09 · 7 scenes · 9 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">follow chords</th><th style="text-align:center;">musician</th><th style="text-align:center;">ties</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../generators/CHAIN">✓</a></td><td style="text-align:center;"><a href="./../generators/FOLLOW_CHORDS">✓</a></td><td style="text-align:center;"><a href="./../generators/MUSICIAN">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td></tr></tbody></table><p><a id="not_werewolves"></a></p><h2 id="outlaw-piano-rock-not-werewolves-yml" tabindex="-1">Outlaw Piano Rock: <code>not_werewolves.yml</code> <a class="header-anchor" href="#outlaw-piano-rock-not-werewolves-yml" aria-label="Permalink to &quot;Outlaw Piano Rock: `not_werewolves.yml`&quot;">​</a></h2><p>An upbeat honky-tonk piano rock song of outlaws on the chords of Warren Zevon&#39;s Frank and Jesse James, opening like saloon music. The piano is the star: a stride left hand, a bass note and a chord for each chord of the song, moved by a Progression and voiced by Voice leading, under a ragtime right hand; the verse two chords a bar on vi I, V I, vi V, IV I; a ballad in the middle; ends on vi.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/rock/not_werewolves.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/rock/not_werewolves.yml</code></a> · G major · 106 BPM · 2:52 · 13 scenes · 9 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">tempo changes</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../generators/CHAIN">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../SCENES#scene-settings">✓</a></td><td style="text-align:center;"><a href="./../generators/PROGRESSION">✓</a></td></tr></tbody></table><p><a id="spot_over_there"></a></p><h2 id="power-pop-spot-over-there-yml" tabindex="-1">Power-Pop: <code>spot_over_there.yml</code> <a class="header-anchor" href="#power-pop-spot-over-there-yml" aria-label="Permalink to &quot;Power-Pop: `spot_over_there.yml`&quot;">​</a></h2><p>An early 2000s power-pop song in the manner of Stacy&#39;s Mom (Fountains of Wayne): muted power chords in the verse, open chords in the chorus, and a key change for the solo. A muted verse on I IV V IV, two chords a bar; a pre-chorus on iii IV; a chorus on IV I V vi; the solo and last chorus a minor third higher.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/rock/spot_over_there.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/rock/spot_over_there.yml</code></a> · A major · 120 BPM · 2:56 · 10 scenes · 9 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">guitarify</th><th style="text-align:center;">ties</th><th style="text-align:center;">key changes</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../generators/CHAIN">✓</a></td><td style="text-align:center;"><a href="./../generators/GUITARIFY">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../SCENES#scene-settings">✓</a></td><td style="text-align:center;"><a href="./../generators/PROGRESSION">✓</a></td></tr></tbody></table><p><a id="training_montage"></a></p><h2 id="arena-rock-training-montage-yml" tabindex="-1">Arena-Rock: <code>training_montage.yml</code> <a class="header-anchor" href="#arena-rock-training-montage-yml" aria-label="Permalink to &quot;Arena-Rock: `training_montage.yml`&quot;">​</a></h2><p>An early eighties arena-rock song in the manner of Eye of the Tiger (Survivor), for a training montage. A muted pulse with chord hits of its own rhythm; a verse on i VI VII i; a chorus on iv VII i i, iv VII VI VI with the band&#39;s answers; a guitar solo over the verse; a breakdown and a last chorus twice.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/rock/training_montage.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/rock/training_montage.yml</code></a> · D minor · 108 BPM · 3:02 · 13 scenes · 11 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../generators/CHAIN">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../generators/PROGRESSION">✓</a></td></tr></tbody></table><p><a id="volcano"></a></p><h2 id="guitar-showpiece-volcano-yml" tabindex="-1">Guitar Showpiece: <code>volcano.yml</code> <a class="header-anchor" href="#guitar-showpiece-volcano-yml" aria-label="Permalink to &quot;Guitar Showpiece: `volcano.yml`&quot;">​</a></h2><p>A solo guitar showpiece in the manner of Van Halen&#39;s Eruption: picked runs, bends, a dive, a fast study and tapped arpeggios, with the opening run coming back at the end. The band hits one chord and leaves; picked runs, bends, a dive, tremolo picking, a study on a circle of chords that a Progression moves, tremolo picking that an AutoRatchet chops into four and a Drift pushes upward, arpeggios tapped in sextuplets by an Arpeggiator on i VI VII V and again wider on i VI iv V, the opening run once more, a last dive and a last chord. It stays out of that solo&#39;s key.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/rock/volcano.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/rock/volcano.yml</code></a> · E minor · 100 BPM · 1:36 · 11 scenes · 5 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">arps</th><th style="text-align:center;">ratchets</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">tempo changes</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../generators/ARPEGGIATOR">✓</a></td><td style="text-align:center;"><a href="./../generators/AUTORATCHET">✓</a></td><td style="text-align:center;"><a href="./../generators/CHAIN">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../SCENES#scene-settings">✓</a></td><td style="text-align:center;"><a href="./../generators/PROGRESSION">✓</a></td></tr></tbody></table><p><a id="why_say_it_again"></a></p><h2 id="new-wave-why-say-it-again-yml" tabindex="-1">New Wave: <code>why_say_it_again.yml</code> <a class="header-anchor" href="#new-wave-why-say-it-again-yml" aria-label="Permalink to &quot;New Wave: `why_say_it_again.yml`&quot;">​</a></h2><p>A taut new wave song of the late seventies in the manner of Psycho Killer (Talking Heads), with a bass line and tunes of its own. A staccato bass alone, then a plain kit and two thin guitars; a clipped verse on a dominant I and a flat VII; a stuttering chorus on flat VI, flat VII and a minor i; a bridge of long notes; a coda of scratching guitar.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/rock/why_say_it_again.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/rock/why_say_it_again.yml</code></a> · D major · 122 BPM · 3:01 · 12 scenes · 9 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../generators/CHAIN">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../generators/PROGRESSION">✓</a></td></tr></tbody></table>',58)])])}const m=t(o,[["render",s]]);export{y as __pageData,m as default};
